import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../auth/presentation/controllers/auth_controller.dart';
class ProfileScreen extends ConsumerWidget{ const ProfileScreen({super.key}); @override Widget build(BuildContext context,WidgetRef ref){ final user=ref.watch(authControllerProvider).valueOrNull; return Scaffold(appBar:AppBar(title:const Text('Profile')),body:SafeArea(child:ListView(padding:const EdgeInsets.all(16),children:[ListTile(leading:const Icon(Icons.person_outline),title:Text(user?.fullName??'User'),subtitle:Text(user?.email??'')),const Divider(),const ListTile(leading:Icon(Icons.settings_outlined),title:Text('Account Settings')),const ListTile(leading:Icon(Icons.notifications_outlined),title:Text('Notification Settings')),const ListTile(leading:Icon(Icons.help_outline),title:Text('Help')),const SizedBox(height:16),OutlinedButton.icon(onPressed:()=>ref.read(authControllerProvider.notifier).logout(),icon:const Icon(Icons.logout),label:const Text('Logout'))])));}}